{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Danazol, a closely related 17-hydroxy steroid, reached 46% absolute oral bioavailability in humans in the fed state, demonstrating that this steroid scaffold can exceed 20% F when absorption is not solubility-limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "In the fasted state, danazol's absolute bioavailability was 19%, just below the 20% threshold, showing that the same scaffold can be solubility-limited and fall below 20% under fasted conditions.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Ethinylestradiol, another 17-hydroxy steroid, had 59% absolute oral bioavailability in humans, supporting high F for the steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Dutasteride, a highly lipophilic steroid-like drug with poor aqueous solubility, has approximately 60% absolute oral bioavailability in humans, indicating that high logP does not preclude F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Esaxerenone, which shares the p-methylsulfonylphenyl and fluorinated substituent motifs with the query, had 89% absolute oral bioavailability in fasting healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Odanacatib, containing methylsulfonyl and trifluoromethyl groups, had 30% absolute oral bioavailability at the 50 mg fasted dose, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer steroid and steroid-like analogues show absolute oral bioavailability well above 20% (ethinylestradiol ~59%, dutasteride ~60%, esaxerenone ~89%, odanacatib 30-70%). The most transferable analogue, danazol, is food-dependent: fasted F is 19% (below threshold) but fed F is 44-67%, indicating solubility-limited rather than intrinsic permeability- or clearance-limited absorption. Given the query's neutral, low-HBD, low-rotatable-bond character and the preponderance of high-F analogues, F≥20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "Food effect and formulation dependence for the query are unknown.",
    "Metabolic stability and first-pass clearance of the query are not experimentally characterized.",
    "No exact structural analogue with the pentafluoroethyl and methylsulfonylphenyl steroid combination is available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

